from pathlib import Path
import json,html,re

OUT=Path(__file__).resolve().parent
ROOT=OUT.parents[1]
REPORT=ROOT/'docs/V2_ENGINEERING_AUDIT_A3_2026_10_13_RU.html'
BEFORE=json.loads((OUT/'source_state_before.json').read_text('utf-8'))
PREFIX='../audit/V2_ENGINEERING_AUDIT_A3_2026_10_13/'
def app(name,label=None):return f'<a href="{PREFIX}{name}">{html.escape(label or name)}</a>'
def src(path,label=None):return f'<a href="../{path}">{html.escape(label or path)}</a>'
def ext(url,label):return f'<a href="{html.escape(url,quote=True)}">{html.escape(label)}</a>'
LMV=ext('https://www.ti.com/lit/ds/symlink/lmv431.pdf','TI LMV431, SNVS041G, с.4,8,14')
CN=ext('https://consonance-elec.com/static/upload/file/20231218/1702867496726953.pdf','Consonance CN3722 Rev1.2, с.4–6')
TPS=ext('https://www.ti.com/lit/ds/symlink/tps63802.pdf','TI TPS63802, SLVSEU9D, §8.3/8.5/9/12')
REZ=ext('https://www.rezonit.ru/directory/tekhnologicheskie-osobennosti-proizvodstva/','Резонит: технологические особенности производства, проверено 13.10.2026')
FW=ext('https://github.com/meshcore-dev/MeshCore/tree/a366955cb2f67b8e6842d4f00d2b6a554dddd88a','MeshCore v1.17.1, a366955cb2f67b8e6842d4f00d2b6a554dddd88a')
F=[]
def finding(n,title,severity,status,where,fact,conditions,evidence,proposal,test,origin):
 F.append(dict(id=f'V2-AUD-{n:03}',title=title,severity=severity,status=status,where=where,fact=fact,conditions=conditions,evidence=evidence,proposal=proposal,test=test,origin=origin))

finding(1,'Ток балансиров LTO не ограничен гарантированно допустимым значением','Критическая','Обоснованный риск; отсутствие гарантии ограничения подтверждено',
 src('design/MeshRepeater2_Power/LTO_Balancer.kicad_sch')+'; U8/U9 LMV431AIM5/NOPB; R47/R51=2 Ω. PCB U8 (30,5;15,6), U9 (12,8;49), R47 (18,2;15), R51 (12,8;45) мм.',
 'LMV431 непосредственно шунтирует ячейку через 2 Ω; отдельного силового ограничителя нет. Рекомендуемый ток катода ≤15 мА, абсолютный непрерывный предел 30 мА. Делитель каждой ячейки Rt=120 kΩ+2,49 kΩ, Rb=100 kΩ. Vz=Vref×(1+Rt/Rb)+Iref×Rt: при Vref=1,24 В и Iref=0,15 µA получается 2,77725 В. Порог без учёта входного тока 2,75888 В не является гарантированным значением.',
 'При Vcell=2,75 В, Vref=1,215 В, Rt−0,1%, Rb+0,1%, Iref=0 (минимум не нормирован), Rs−1% идеализированный расчёт даёт Vz≈2,70028 В и Ik≈25,1 мА. При условных 2,85 В и типичных параметрах — около 36,4 мА. Эти оценки показывают отсутствие гарантированного запаса; за пределами нормированного режима модель шунта не предсказывает фактический ток или разрушение. Допустимость 2,85 В для неизвестной ячейки не утверждается. Контроль только суммы напряжений не ограничивает разбаланс каждой ячейки.',
 LMV+'; '+app('ELECTRICAL_native_evidence.json')+'; '+app('ELECTRICAL_calculations.json')+'. TI нормирует Vref при Ik=10 мА и динамическое сопротивление только в установленном диапазоне. C58/C59=47 nF не объявляются доказанной причиной неустойчивости: типовая Fig.19 этого не подтверждает.',
 'После выбора ячейки обеспечить Ik≤15 мА на всех заявленных углах: рассчитанный балласт/ограничитель либо внешний силовой шунт, если нужен больший ток балансировки. Изменение 2 Ω требует отдельного согласования; здесь оно не внесено.',
 'Два изолированных эмулятора ячеек, ток ограничен внешним источником. Измерять Vcell, ток R47/R51 и температуру U8/U9 в холоде/тепле и при максимальном зарядном токе. Приёмка: Ik≤15 мА; напряжение каждой ячейки в её паспорте; отсутствуют устойчивые колебания, перегрев и превышение абсолютных пределов.',
 'Унаследовано из S4.16. '+src('audit/fixes_2026_10_12/user_decision.json','Решение 12.10.2026 сохранить 2 Ω и ограничения')+' сохраняется, но не подтверждает безопасность.')

finding(2,'Вход TPS63802 в LTO может выйти за рабочие 5,5 В при снятой батарее','Критическая','Обоснованный риск; несовместимость гарантированных диапазонов подтверждена',
 src('design/MeshRepeater2_Power/MeshRepeater2_Power.kicad_sch')+' U1.14/R3/R4; '+src('design/MeshRepeater2_Power/Converter.kicad_sch')+' U2.10. BAT_SYS → U2 напрямую; J11 стоит на выходе.',
 'LTO R3=121 kΩ, R4=100 kΩ, 0,1%, ≤25 ppm/°C. Vreg=VFB×(1+R3/R4)+IFB×R3. При VFB=2,392…2,44 В, IFB≤300 nA и ±(0,1%+25 ppm×65°C) рассчитаны: CV тип 5,34541 В, верхний 5,44434 В. Это укладывается в 5,5 В в установившемся режиме. Однако CN3722 допускает при отсутствии/отсоединении батареи свой OVP 1,06…1,10×Vreg: тип 5,77304 В, верхний 5,98877 В. Рабочий VIN TPS≤5,5 В; абсолютные 6 В не разрешают работу выше 5,5 В.',
 'SOLAR подключён, LTO батарея отсутствует/внезапно отсоединена, нагрузка мала. Снятие J11 не разрывает BAT_SYS→U2.10. Балансиры включены в проверенную цепь BAT_SYS→R71→BAT→R47→U8→MID→R51→U9→GND: их типовая сумма порогов около 5,5545 В уже выше 5,5 В. Статическая оценка при 5,773 В даёт около 53 мА через каждый LMV, но за пределами его нормированного режима не является прогнозом реального тока. Поэтому эти шунты нельзя считать гарантированным ограничителем. Возможны работа TPS вне паспорта и повреждение; достижение абсолютных 6 В не доказано.',
 CN+'; '+TPS+'; '+app('ELECTRICAL_calculations.json')+'; свежие '+app('POWER_netlist.xml','POWER XML')+' и native pads в '+app('ELECTRICAL_native_evidence.json')+'. Выброс на образце не измерен.',
 'Для безусловного требования «до 5,5 В во всех режимах» нужна независимая отсечка/ограничение с учётом допусков и выбросов либо преобразователь с большим рабочим VIN. Пересчитать совместно с V2-AUD-001. Прежнее решение не добавлять защиту сейчас не изменено.',
 'Эмулятор LTO, регулируемый SOLAR до подтверждённого холодного Voc, лёгкая и максимальная нагрузка, подключение/отключение батареи. Одновременно осциллограф U2.10–U2.8, BAT, MID и токи балансиров. Приёмка: U2.10≤5,5 В во всех заявленных режимах и сохранение пределов обеих ячеек/LMV. Начинать с отдельного внешнего контроля/ограничения BAT_SYS.',
 'Унаследованный, ранее принятый риск; позднее требование «точно до 5,5 В в любой ситуации» и выбранная схема не образуют гарантии этого условия.')

finding(3,'Нет данных для квалификации заряда и разряда конкретных аккумуляторов и панели','Высокая','Непроверенный вопрос из-за отсутствия данных',
 'POWER U1, R1/R56, R3/R4, R15/R16, TH1/U10/U11, Q1, J7/J8/J12; варианты Na-ion COLD, Na-ion NoCOLD, LTO 2S.',
 'Ни модель Na-ion/LTO ячеек, ни схема защиты пакета, ни Vmp/Voc и холодный Voc панели не закреплены. Основной ток CN тип 0,200/0,28=714 мА, угол VCS=215 mV и R1−1% даёт 775,6 мА без неизвестного TCR. COLD: 0,200/(1,8+0,28)=96,15 мА, верхний угол 104,4 мА. Это ток зарядного выхода, часть которого потребляет устройство. Na CV тип 3,91460 В, верхний 3,97693 В ниже согласованных 4,0 В в steady state.',
 'TEMP U1.6 зафиксирован R9 на GND: штатный температурный контроль отключён. COLD снижает ток, а не запрещает заряд; TH1 под экраном измеряет температуру платы, которая может быть выше температуры внешней батареи. Горячее отключение по температуре ячейки не задано. EN измеряет BAT до R71: Na OFF тип 1,8056 В, рассчитанный разброс 1,7499…1,8695 В; приблизительно 1,74 В пользователь позднее согласовал, поэтому это не нарушение старого точного 1,8 В. LTO OFF 3,492…3,745 В относится к пакету, не к каждой ячейке. Q1 |VDS|30 В/|VGS|12 В, CN вход≤28 В, C8 35 В: неизвестный холодный Voc и выбросы не позволяют подтвердить запас.',
 CN+'; '+TPS+'; '+app('ELECTRICAL_calculations.json')+'; '+app('ELECTRICAL_FINDINGS_RU.md','подробности температурного узла и точных выбранных дросселей/ключа')+'. NTC open/short направляют узел к малому току; это не проверка химии.',
 'Закрепить паспорта ячеек/пакета и панели, допустимый ESR, зарядный ток по температуре, индивидуальные пределы LTO, предзаряд и допустимость CV. Если нужна температура ячейки — датчик на батарее либо подтверждённая тепловая связь. Корректировать схему только после установленного несоответствия.',
 'Измерять ток J8/J12 и напряжение каждой ячейки, температуру батареи и TH1, SOLAR/VBAT на крайних заданных температурах, при бедной/максимальной инсоляции и NTC open/short. Приёмка по выбранному паспорту ячеек, а не общему названию химии; напряжения деталей в recommended range. Без паспортов критерии заряда завершить нельзя.',
 'Ранее недостающие данные и принятый отказ от штатной температурной защиты; наличие COLD — поздняя согласованная опция, не отменяющая этот пробел.')

finding(4,'LC, пуск и автономное восстановление после разряда требуют квалификации','Высокая','Обоснованный риск; не доказана неустойчивость преобразователя',
 src('design/MeshRepeater2_Power/Converter.kicad_sch')+' U2/C12/C52/C14/R55/L3/L4/R40/R41; '+src('design/MeshRepeater2_Power/BatteryMonitor.kicad_sch')+' R71=0,1 Ω.',
 'FB U2 снимается с SYS_PRE до R55=47 mΩ и двух 2,4 µH дросселей. R40/R41=22 mΩ стоят в ёмкостных ветвях, не последовательно нагрузке. Каждая банка содержит 10×100 µF TDK C4532X5R1A107M280KC (номинал 1000 µF); гарантированные ≥330 µF при 3,3 В с температурой/старением пока не подтверждены. Локально установлен C52=10 µF, он не резерв DNP. Минимум TI: Cin≥4 µF, Cout≥7 µF эффективных. Установленные резервы нельзя подменять потенциальными площадками C53/C54/C55.',
 'Пассивный AC-расчёт 18 углов (L±30%, Cbank=330/1000 µF, R55/R40/R41 и DCR=10,5 mΩ, 10 Hz…100 kHz) даёт max transfer 1,392 при ~2,606 kHz и |Zout|max ~0,150 Ω при ~2,897 kHz. Источник идеален; TPS-loop/контакты/ESR/ESL/нагрузка не моделировались, поэтому самовозбуждение не доказано. DC только R55+2DCR при 0,5 А: 34 mV. Условный сценарий η=0,9, Voc ячейки=2,0 В, ESR=0,2 Ω, R71=0,1 Ω и выход=1,65 W даёт I≈1,097 А, BAT≈1,781 В ниже типового OFF, затем после отключения BAT восстанавливается выше ON≈1,986 В: возможны циклы EN. ESR/КПД не измерены. EN до R71, поэтому прямую положительную обратную связь через шунт не заявляем. Заряд только двух банков≥660 µF требует Q≥2,178 mC/E≥3,594 mJ; фактический inrush зависит от soft-start.',
 TPS+'; '+ext('https://product.tdk.com/en/search/capacitor/ceramic/mlcc/info?part_no=C4532X5R1A107M280KC','TDK: точный MPN, кривые справочные')+'; '+app('ELECTRICAL_LC_PASSIVE.json')+'; '+app('ELECTRICAL_RECOVERY.json')+'. Оценки относятся к заданным допущениям, не осциллограммам.',
 'Сначала подтвердить Ceff, реальный ток нагрузки/ESR источника и recovery. При установленном провале — уменьшить импеданс/подобрать ёмкости или демпфирование, изменить пусковой запас/гистерезис либо последовательность включения нагрузки. Изменение шунта требует новой калибровки INA и согласования.',
 'Эмулятор с паспортным max ESR; BAT min/max, SOLAR on/off, банки заряжены/разряжены, TX+GPS, PFM/PWM. Снимать BAT у R15.1, BAT_SYS U2.10, EN U2.1, SYS_PRE, FILTER_OUT, M1.9/M2.3 относительно местной земли. Критерии: Cin≥4/Cout≥7 µF, каждый банк≥330 µF при 3,3 В в заданных условиях; VIN>1,8 В до PG согласно TI, затем паспортные напряжения потребителей; один автономный запуск после восстановления, без циклов EN/UVLO/reset и устойчивых колебаний.',
 'Унаследованный LC и низковольтный Na режим, дополнительное падение согласованного INA219/R71 в v2. CAD-правильность не заменяет динамическую проверку.')

finding(5,'USB должен питать всю сборку через неизвестный LDO клона; остаточные сигнальные токи не проверены','Высокая','Непроверенный вопрос и обоснованный риск',
 'POWER J11/NT2/J101, LOGIC J201/M1/M2/R21, POWER U2.MODE/R17; BAT_ADC R27/R28/C25.',
 'J11.1=FILTER_OUT, J11.2=SYS_3V3; NT2 соединяет SYS и RADIO только после J11. Снятый шунт действительно разрывает силовую медь LC→SYS. При USB на M1 питание SYS возвращается по J201.1/3 на POWER; NT2 питает RADIO по .5/7, а также INA219/RTC/watchdog/GPS. Следовательно, USB-LDO модифицированного Nice!Nano должен выдерживать полную нагрузку, а не только MCU. Точная микросхема/модификация клона и её бюджет документально не определены.',
 'J11 установлен одновременно с USB — соединяются источники, возможен обратный поток. При J11 open остаются сигналы: RADIO_TXEN→R21=1 kΩ→MODE, R17=100 kΩ к GND; BAT→R27=2,2 MΩ→M1.8. Предел MODE 6 В указан независимо от VIN, поэтому USB 3,3 В при BAT=0 не объявлены absolute violation. Но Ioff MODE не гарантирован; слабую инжекцию и остаточное питание надо измерить. При BAT=4 В верхняя ограниченная оценка тока через R27<1,82 µA. Это не силовой обход J11.',
 app('POWER_netlist.xml')+'; '+app('LOGIC_netlist.xml')+'; '+app('SCHEMATIC_EQUIVALENCE_FRESH.json')+'; '+TPS+'. Пользовательскую проверку конкретного клона учитываем, но её режимы/результаты не известны.',
 'Описать фактическую аппаратную доработку и квалифицировать USB-LDO на полной нагрузке. При провале нужен рассчитанный источник/разделение источников. Сохранить единственный J11 и обязательный порядок снятия до USB; вмешательство сейчас не внесено.',
 'J11 open; USB с BAT/SOLAR присутствующими и отсутствующими; TX+GPS максимальной длительности. Измерять M1.9, M2.3, USB ток/температуру LDO, BAT_SYS/FILTER_OUT/MODE при выключенной батарее, обратный ток в USB при BAT. Норма тока/нагрева и reverse current — из паспорта реального LDO; отсутствие отказов/reset и напряжения модулей в их рабочих диапазонах.',
 'Прямое питание 3V3 и аппаратная доработка клона ранее согласованы; перенос J11/разделение ветвей A3 проверены заново.')

finding(6,'Номинальная сборка проходит, гарантированные допуски разъёмов и крепежа не закрыты','Высокая','Непроверенный вопрос; невозможность реальной сборки не доказана',
 'POWER J101 (64,15;11), LOGIC J201 (64,15;49), SHIELD окно 17,2×6,8/R0,6; стойки 18/15 мм, M3×6, 20 шайб DIN433 0,5 мм; M1/M2/USB оболочки.',
 'Выбраны Ali E-SIMPO L35mm A3C6/2×6P и MTJ H8.5/2×6P, но нет документа изготовителя точной пары с окном ввода/максимальным пластиком/сечением штыря и допусками. Номинал G=18+15+1,52+3×0,50=36,02 мм; D=35−3−36,02+8,5=4,48 мм. До краёв окна при модельном пластике 15,64×5,0 мм остаётся 0,78/0,90 мм на сторону. Номинальный drill 1,02 мм против диагонали условного штыря 0,64×0,64=0,905 мм даёт лишь 0,115 мм диаметрального запаса.',
 'Worst-case TD=TL+TPC+T18+T15+Tshield+3Twasher+THf неизвестен. Возможны неполный контакт/изгиб/касание фольги, хотя свежие STEP дают 0 пересечений. Верхний ввод резьбы=6−1,52−2×0,5=3,48 мм, нижний доступный=5−1,52−0,5=2,98 мм. После допуска верхней шпильки ±0,2 мм остаётся всего 0,28 мм на PCB/шайбы/неполные витки до проектного ≥3 мм; полезная глубина неизвестна. Высоты NiceNano/HT-RA62 и доступ Type-C/shunt/кабельных оболочек модельные, не гарантированные габариты. Каждый силовой контакт проверять на полный ток ветви: равное распределение по двум пинам не гарантировано.',
 app('MECHANICAL_RF_REPORT_RU.md')+'; '+app('MECHANICAL_RF_brep.json')+'; '+src('docs/vertical_interconnect_selection.json')+'; '+src('docs/mechanical_selection.json')+'; '+ext('https://aliexpress.ru/item/1005011978353933.html?sku_id=12000057202232448','точная выбранная вилка')+'; '+ext('https://aliexpress.ru/item/1005008954873458.html?sku_id=12000047353417475','выбранная розетка')+'. Карточки не заменяют паспорт совместимости.',
 'Квалифицировать купленную пару и размерный макет окна/стека; измерить предельные габариты, ввод, резьбу, реальные модули и кабели. Корректировать длину/высоту/drill/окно только при провале. При отсутствии гарантии изготовителя квалификация относится к проверенной партии.',
 'Без питания собрать POWER→экран→LOGIC без притягивания разъёмов винтами; окно надевается через пластик свободно, пины не касаются фольги. Контакты 1:1 и NC8 изолированы; ввод внутри подтверждённого окна сопряжения. Верхние соединения ≥3 мм полных витков, нижняя гайка полностью зацеплена, крепёж не упирается до зажима. Затем полный ток каждой ветви/пики, падение контактов, многократная разборка по согласованному протоколу. USB/кнопки/J11/SMA доступны реальными ответными частями; ISP только после разборки.',
 'Поздние вертикальные Ali-разъёмы и окно имеют приоритет над исходными IDC/отдельными отверстиями. Номинальная A3 геометрия подтверждена, реальные допуски — нет.')

finding(7,'Официальные карты GPS расходятся по питанию контактов 6/7','Высокая','Непроверенный вопрос; неверная разводка A3 не доказана',
 'LOGIC J4.6=SYS_3V3 постоянно, J4.7=GPS_3V3 переключаемое; Q2/Q3/U7, P0.24 GPS_EN.',
 'Heltec MeshNode-T114_V2.1 P3 показывает .6=Ve_3V3 от U5, .7=VDD_nRF. Официальная карта аксессуара L76K показывает .6=VDD_3V3, .7=Ve_3V3 и совпадает с A3. У самого L76K вывод 6=V_BCKP, 8=VCC. Без точного аксессуара и карты двух концов кабеля произвольный выбор одного документа не разрешает противоречие.',
 'Несоответствующий кабель может оставлять основное питание включённым, снимая backup, либо нарушить связь с отключённым U7: лишний расход, потеря горячего старта, отказ UART. Повреждение от двух 3,3-В цепей не доказано. Штатный UART GPIO A3 совпадает с исследованной прошивкой.',
 ext('https://resource.heltec.cn/download/Mesh_Node_T114/schematic/MeshNode-T114_V2.1.pdf','Heltec T114 V2.1, единственный лист, P3')+'; '+ext('https://heltec.org/wp-content/uploads/2025/07/L76K-Pin-map-1024x733.png','Heltec: карта аксессуара L76K')+'; '+ext('https://heltec.org/wp-content/uploads/2025/07/L76K_pinmap.png','Heltec: выводы ядра L76K')+'; '+app('SOFTWARE_BOM_REPORT_RU.md')+'. Первичные изображения сохранены в приложениях.',
 'Закрепить точный модуль/ревизию и прозвонку кабеля; затем при необходимости изменить только карту .6/.7 либо документировать требуемый перекрёстный кабель. До проверки не подключать неизвестный GPS.',
 'Прозвонить J4.6→L76K V_BCKP и J4.7→VCC для выбранного аксессуара; затем GPS_EN on/off: измерять J4.6/7, V_BCKP/VCC, U7.8 и ток. Приёмка: backup сохраняется, основное питание управляется P0.24, UART работает при on, паразитное питание/ток при off в паспорте аксессуара.',
 'Исходное требование аналогичного T114 сохранено, но его точная внешняя кабельная карта неоднозначна в первичных документах.')

finding(8,'Несколько действующих указателей ведут к прежней комплектации A2','Средняя','Подтверждённый дефект документации и идентификации редакции',
 src('bom/NOTES_RU.txt')+' строка 4; заголовки POWER/LOGIC PCB; '+src('output/pdf/SCHEMATIC_MANIFEST.json')+'; вводные абзацы '+src('docs/V2_CHANGES_FROM_S4_16_RU.md')+'.',
 'NOTES называет актуальной V2_COMPONENT_BOM.csv прежней A2: там R1/R40/R41/R55=1206, R56=0805, J11 на LOGIC. Фактическая A3 имеет эти шесть силовых позиций в 2512 и J11 на POWER. Корректная V2_A3_COMPONENT_BOM.csv существует и согласована по 179 позициям. В native PCB POWER/LOGIC title_block остаётся V2.0-A2/12.10, SHIELD уже A3/13.10. Общий PDF manifest относится к A2. Действующее описание изменений всё ещё начинает с кабеля/J11 LOGIC/шести GND, хотя текущая вертикальная пара имеет три GND.',
 'Закупка или заказ через неверный указатель приводит к несовместимым корпусам, неверной сборке/идентификации. Это одна причина — неполная актуализация указателей редакции; отдельные проявления объединены. Старые A2 PDF, которые README прямо помечает историческими, сами по себе не являются дефектом и не включены сюда.',
 app('SOFTWARE_BOM_checks.json')+'; '+app('SOFTWARE_BOM_REPORT_RU.md')+'; native файлы/CSV выше. 44 текущих экспортных артефакта привязаны к фактическим PCB своими SHA; A3 схемные PDF корректно показывают текущий J11/pinmap.',
 'При отдельной задаче обновить только действующие указатели, PCB title/date и манифесты текущего выпуска; исторические файлы сохранить с явной редакцией. Зафиксировать единый перечень основных A3 документов и BOM.',
 'Dry-run сборщика: от README/NOTES получить только текущую BOM, 2512, J11 POWER, SYS1/3/RADIO5/7/GND2/4/6/NC8. Сверить title/manifest/source SHA всех выпускаемых файлов; старые документы не должны называться текущими.',
 'Новая проблема согласованности A3 документации; опубликованная A2 не должна выдаваться за текущую рабочую редакцию.')

finding(9,'Направления UART GPS в инструкции описаны наоборот','Средняя','Подтверждённый дефект только документации',
 src('docs/V2_ASSEMBLY_INSTRUCTIONS_RU.md')+' строки 154–155; LOGIC J4.4/J4.5/U7/M1.',
 'J4.4 GPS_RX_EXT описан как приём MCU, но фактически M1.20/P0.20 TX→U7.2→U7.6→J4.4. J4.5 GPS_TX_EXT описан как передачa MCU, но фактически J4.5→U7.5→U7.3→M1.19/P0.22 RX. Названия сетей со стороны GPS допустимы; неверна колонка роли MCU.',
 'При изготовлении кабеля по роли MCU могут поменять RX/TX и получить неработающий UART. Сама схема, footprint buffer и проверенная прошивка направления сохраняют; менять GPIO не требуется.',
 app('LOGIC_netlist.xml')+' строки 3647–3663; '+FW+' EnvironmentSensorManager.cpp:735 вызывает setPins(PIN_GPS_TX,PIN_GPS_RX), а закреплённое ядро d541301 Uart.h:37 принимает (rx,tx). Получается RX=P0.22/TX=P0.20, что совпадает с CAD; '+app('SOFTWARE_BOM_REPORT_RU.md')+'.',
 'Исправить два описания на «TX MCU → RX GPS» и «TX GPS → RX MCU» с указанием стороны названия сети. Электрические связи оставить.',
 'Прозвонить кабель и измерить UART TX/RX на J4.4/.5; loopback и реальные сообщения выбранного GPS. Инструкция должна однозначно совпадать со свежим XML.',
 'Документация текущей A3; это не найденная перестановка портов FakeTec.')

finding(10,'Маркировка ниже опубликованных минимальных норм Резонита','Средняя','Подтверждённое несоответствие опубликованной возможности; выбор сервиса условен',
 'F/B.Silkscreen всех трёх плат; ограничения .kicad_pro и фактические видимые тексты.',
 'Резонит публикует минимум высоты шрифта 1,0 мм и линии 0,15 мм. В native POWER min 0,8/0,12: 190 из 194 видимых текстовых объектов ниже одного из этих пределов; LOGIC 89/89; SHIELD min 0,85/0,13, 20/28. Это объекты текста, не количество компонентов/букв. Внутренние правила позволяют шрифт 0,8 и толщину 0,1, поэтому нулевой DRC не проверяет требования производства. При меди 35 µm минимальная POWER дорожка 0,15 мм требует опубликованного более тонкого техпроцесса; базовый предел 0,20 мм. Зазоры 0,20 и via drill/annular 0,30/0,15 мм укладываются в опубликованные базовые пределы.',
 'При заказе без письменного согласования возможны исчезновение тонких надписей/коррекция CAM, ухудшение читаемости вариантов и перемычек. Тонкие дорожки не объявлены неизготовимыми: у Резонита предусмотрен соответствующий сервис. Производственный пакет был отложен, окончательный техпроцесс ещё не выбран.',
 REZ+'; '+app('MANUFACTURING_GEOMETRY.json')+' (для каждого текста UUID/слой/координаты/шрифт/толщина); '+app('NATIVE_CHECKS.json')+'. Данные магазина не использованы как производственные правила.',
 'Для Резонита либо увеличить высоту/штрих с повторной компоновкой, либо получить письменное DFM-согласование; выбрать техпроцесс для фактических 0,15 мм или локально расширить трассы. В аудит правила и графика не менялись.',
 'Свежий экспорт будущего комплекта, CAM preview и DFM выбранного сервиса: изготовитель подтверждает минимальные тексты и фактические width/clearance/drill/annular. Проверить читаемость на физическом масштабе и изготовленном образце; без согласования текущая маркировка не получает PASS для Резонита.',
 'Внутреннее требование ≥0,8 мм выполнено, но оно мягче опубликованного производственного ограничения. Не ошибка электрической связности.')

finding(11,'Штатный коэффициент BAT ADC не соответствует идеальному делителю 1:2','Средняя','Обоснованный риск точности; фактическая ошибка не измерена',
 'LOGIC R27/R28=2,2 MΩ, C25=100 nF, M1.8 BAT_ADC; MeshCore PromicroBoard.h ADC_MULTIPLIER=1,815.',
 'При reference=0,6 В, gain=1/6, 12 bit и делителе 1:2 идеальная шкала 2×3,6/4096=1,7578125 mV/count. Штатный множитель 1,815 даёт +3,2533%: условные 3,915 В отображаются как 4,042 В. Это расчёт номинального ADC, а не измеренная погрешность реального клона. Rth=1,1 MΩ, τ=Rth C25=110 ms; до 1% ~507 ms, до 0,1% ~760 ms. Статическая ошибка ΔVADC=Ileak×1,1 MΩ, на BAT вдвое больше. Конденсатор помогает выборке, но не устраняет DC-утечку.',
 'Неоткалиброванная телеметрия батареи и высокий импеданс при утечках/загрязнении/температуре. Аппаратные CV и EN от программной шкалы не зависят, поэтому опасный заряд/отключение из одного коэффициента не выводится.',
 FW+' PromicroBoard.h/PromicroBoard.cpp; '+app('SOFTWARE_BOM_checks.json')+' adc_ideal_calculation; '+app('ELECTRICAL_FINDINGS_RU.md')+'.',
 'Измерить передаточную характеристику и записать поддерживаемую настройку ADC multiplier. Сохранять GPIO и экономный делитель; снижать импеданс только если измеренный бюджет утечек не проходит.',
 'В каждом варианте подать min/mid/max BAT, выдержать ≥5τ=0,55 с для сравнения с DMM; снять BAT у J8/J12, M1.8 и телеметрию при TX/off/USB. Согласовать допустимую точность заранее и проверить её во всём диапазоне температуры/источников. 5τ не является обещанием точности 0,1%.',
 'Высокоомный делитель ранее согласован; калибровка прошивки/реального клона осталась незавершённой.')

finding(12,'RF/BLE и подавление помех ещё не подтверждены измерениями','Средняя','Обоснованный риск; EMI/RF дефект не доказан',
 'LOGIC M2 ANT→FL1/NT1→J13; FB1/C23/C24; M1 BLE antenna; POWER U1/L1 и U2/L2; открытый промежуточный SHIELD.',
 'RF F.Cu ширины 1,3/0,8 мм, gap в серединах 0,250499 мм, противоположная GND присутствует; цифровой разрез под основными ANT-отрезками не найден. У SMA launch локальная осевая область ~1,25 мм занята сигнальной площадкой/clearance, вокруг есть земля и четыре анкера: это не доказанный разрыв возврата. Разные ширины/переходы/площадки и неизвестный stackup не подтверждают ровно 50 Ω. M2 band variant TBD должен быть закреплён как HF для ~869 MHz. C24 находится в 2,4 мм от M2.3, RADIO имеет локальную фильтрацию.',
 'SHIELD — открытая пластина, а не замкнутый кожух. Длина switching net D1-K→L1 ~13,76 мм; TPS LX1/LX2 по 2,184 мм, в том числе короткие ~1,066 мм сегменты шириной 0,20 мм. Непрерывная земля и короткие локальные цепи помогают, но не гарантируют отсутствие наведённых шумов/нагрева. Экран под BLE клона может менять согласование. Общий импеданс GND/источника остаётся даже при отдельных положительных SYS/RADIO ветвях.',
 app('MECHANICAL_RF_native.json')+'; '+app('MECHANICAL_RF_checks.json')+'; '+app('ROUTING_GEOMETRY_FRESH.json')+'; '+ext('https://resource.heltec.cn/download/HT-RA62/HT-RA62%28Rev1.1%29.pdf','Heltec HT-RA62 Rev1.1, с.4–9')+'; '+ext('https://resource.heltec.cn/download/HT-RA62/HT-RA62_Reference_design.pdf','Heltec reference design')+'; '+TPS+'. Нет измерений spectrum/чувствительности/температуры.',
 'Закрепить HF-ревизию/ANT-комплектацию модема, клон и stackup; проверить RF-модель/образец. Изменения трассы/экрана оправданы только найденным отклонением. Утверждения соответствия EMI-стандарту без заданного стандарта и испытаний не делать.',
 '50-Ω нагрузка SMA, фактический radio profile; измерять мощность/спектр и PER/чувствительность при PFM/PWM, зарядке off/max, экране fitted/removed, BLE при постоянной дистанции/ориентации. Отдельно осциллограммы M1/M2 при TX и нагрев силовых узлов. Численный бюджет допустимого ухудшения EMI/BLE/RF в ТЗ отсутствует — сначала определить протокол и предел, а не назначать произвольный PASS.',
 'Унаследованная RF часть и новое экранирование/стек v2; нулевой DRC и BRep не доказывают радиопараметры.')

finding(13,'Устанавливаемая SAW-опция требует отдельного температурного и радио-профиля','Критическая только при FL1 fitted и превышении мощности','Обоснованный условный риск; паспортные ограничения подтверждены',
 'LOGIC FL1 S869M000S003, NT1 под фильтром; стандартно FL1 DNP/NT1 замкнут.',
 'Abracon RevA, printed с.2: Source Power≤13 dBm, operating −10…+65°C, полоса 868…870 MHz. В проекте предупреждение 13 dBm есть, полный температурный предел опции не приведён. Исследованный ProMicro profile задаёт +22 dBm; его нельзя автоматически использовать с установленным фильтром. Хранение −40…+85°C не является рабочим диапазоном. Printed с.3 рекомендованный land drawing неоднозначен: 0,4 мм в верхнем ряду против 0,8 мм и общей геометрии; локальный footprint документирует выбор 0,8 мм. Корпус 3×3×1,3 мм и pin2 IN/pin5 OUT/остальные GND совпадают.',
 'Базовая DNP сборка не нарушает паспорт отсутствующей детали. При монтаже FL1 и сохранённой высокой мощности возможна работа вне рейтинга/повреждение; при морозе ниже −10°C параметры не гарантированы. Это условие конкретной опции, а не подтверждённый отказ основной платы. Неоднозначность lands — отдельная часть квалификации именно этого узла, не доказанная неправильная пайка.',
 ext('https://abracon.com/datasheets/AEL-Crystals/PN/S869M000S003.pdf','Abracon S869M000S003 RevA, printed с.2–3')+'; '+FW+' variants/promicro/platformio.ini; '+app('MECHANICAL_RF_REPORT_RU.md')+'.',
 'Зафиксировать для FL1 профиль мощности/частоты/температуры до монтажа и получить подтверждение lands либо квалифицировать партию. Для более холодной/мощной работы выбрать другую документированную опцию; сейчас её не заменять.',
 'После резки NT1 при снятом FL1 ANT_RF–ANT_SMA должны быть разомкнуты; после монтажа осмотр шести lands, VNA в 50 Ω: IL≤2,5 dB, ripple≤1 dB в 868…870 MHz в допустимом режиме. Мощность непосредственно на входе FL1≤13 dBm, температура детали −10…65°C. Эти критерии не квалифицируют всю антенну/морозную эксплуатацию.',
 'Ранее согласованная опция без разрыва NT1 в базовом варианте; требует отдельной комплектации и программной настройки.')

finding(14,'Комплект закупки LTO и часть сборочных позиций не завершены','Средняя','Непроверенный вопрос комплектности; новое наличие проверено',
 src('bom/V2_A3_COMPONENT_BOM.csv')+'; LTO R15/C30, R48/R49/R50/R52/R53/R54/C58/C59; '+src('bom/DAN_NEW_PARTS.csv')+' J12_HARNESS; сокеты M1.',
 '10 устанавливаемых LTO-позиций имеют MPN not selected/TBD. Точная комплектация двух рядов сокетов M1 с требуемой высотой не выделена закупочным набором. Основной товар ДАН 205451 (кабельный корпус L-KLS1-2.50-04-H для J12) на 13.10 отсутствует. Остаток 413 из прежней проверки 11.10 не является текущим наличием; число у рекомендованного товара на странице не принято за остаток основного. Остальные 13 новых основных карточек прочитаны; верхние стойки 188548 теперь 166 шт. вместо 168. GPS-комплект/M2 диапазон разобраны в V2-AUD-007/012, не повторяются как новые дефекты.',
 'Можно заказать неполную LTO сборку/неподходящую точность или высоту. Отсутствие товара сегодня не доказывает ошибочность прежнего датированного наличия. NiceNano и модем по условию закупаются отдельно; произвольная замена их не предложена.',
 app('SOFTWARE_BOM_checks.json')+' dan_cards/bom; '+ext('https://www.danomsk.ru/shop/7-kommutatsiya/121-razemy/306-soediniteli-pryamougolnye/205451-chu-4-xh-04f-l-kls1-2-50-04-h-rozetka-kabelnaya-bez-kontaktov-kontakty-203549-203367-2-5mm-kls/','ДАН 205451, проверено 13.10.2026')+'; '+app('SOFTWARE_BOM_REPORT_RU.md')+'. Карточка 199312 имеет несколько имён кнопки: заказывать именно документированную TE 1825027-2.',
 'Закрепить LTO MPN с рассчитанными допусками/ТКС/корпусами, полный набор сокетов и ответных частей; найти тот же J12 корпус у другого поставщика либо отдельно квалифицировать замену. Проверять наличие непосредственно перед закупкой.',
 'Dry-run одного полного выбранного варианта: количество, Fit/DNP, маркировка, точность/TCR, mating, корпуса и обжимные контакты. Для J12 достаточно трёх предусмотренных контактов в четырёхполюсном корпусе; NC не превращать в случайную батарейную цепь.',
 'Незавершённый этап подбора/закупки, а не выявленное нарушение native BOM A3.')

finding(15,'Сборка основной прошивки и стендовая квалификация функций не завершены','Средняя','Непроверенный вопрос; ошибка среды сборки не является доказанным дефектом проекта',
 'Внешний MeshCore SHA a366955cb2f67b8e6842d4f00d2b6a554dddd88a, source v1.17.1, env ProMicro_repeater; '+src('design/watchdog_reference/main.c')+' и HEX; текущая инструкция прошивки.',
 'GPIO радио/I²C/GPS, RTC0x68/INA2190x40 согласованы с этим source. Watchdog пересобран AVR GCC7.3.0: Flash406 B/RAM4 B, HEX совпал SHA256 8d38a4213ea91b9ad8d99638ac21ccfd80c2d75d24d1545856dba421195e5790. Полная MeshCore попытка реально выполнена в изолированном scratch: PIO6.2.0, nordicnrf52@11.0.0, ARM GCC7.2.1, framework1.10701.0+sha.d5413016 и зафиксированные библиотеки. Windows longpaths checkout обойдён только env процесса. SDK-компиляция затем остановилась на bits/c++config.h; отдельный probe воспроизвёл отказ без MeshCore. Canonical CPLUS_INCLUDE_PATH дал probe PASS и прошёл этот этап, но следующая сборка остановилась на assembler object paths 262–268 символов. HEX/ELF MCU не получены.',
 'Не закреплён фактический прошиваемый бинарник/все runtime radio/ADC настройки. Нельзя обещать подтверждённый запуск этого клона. Watchdog отслеживает только TXEN: штатное молчание ~3 часа также вызывает reset, а собственный WDT ATtiny в interrupt-only не перезапускает зависший U6. Это сохранённое назначение, не новая ошибка. UART J5 зависит от environment: GPS использует Serial1, bridge environment его переназначает; одновременность не доказана. Измерений boot/RTC/GPS/INA/reset нет.',
 FW+'; '+app('SOFTWARE_BOM_MAIN_BUILD_RESULT.json')+'; '+app('SOFTWARE_BOM_BUILD_COMMAND.txt','точные команды сборки')+'; '+app('SOFTWARE_BOM_BUILD_TMP/platformio_build_canonical.log','последний build log')+'; '+app('SOFTWARE_BOM_REPORT_RU.md')+'. Ошибка инфраструктуры не выдана за ошибку аппаратуры или кода.',
 'В отдельной подготовленной среде с короткими путями завершить чистую сборку указанного SHA/environment, сохранить бинарник с SHA и lock зависимостей/runtime profile; затем квалифицировать установленный модуль. Алгоритм watchdog менять только отдельным согласованным решением, если испытания покажут несоответствие назначению.',
 'Загрузка/boot/radio_init, ACK RTC0x68/INA0x40, GPS on/off, ADC/INA сравнение с эталоном, RTC время/OSF и сохранение от CR2032. Для watchdog измерять TXEN M2.5/7, U6.2 и MCU_RESET U6.5: TX сбрасывает ожидание, молчание вызывает ограниченный LOW и успешный restart. 1350×8 s=10800 s лишь номинал; реальную длительность установить по измеренной частоте. ISP3,3 В, fuses LF7B/HFFB, SCK≈10 kHz<128 kHz/4; readback. Не объявлять покрытым отказ самого U6.',
 'Незавершённая воспроизводимость/испытания, не найденный дефект текущего GPIO-контракта. Прошивка v1.17.1 — проверенный source для сравнения, а не доказанно загруженный пользователем бинарник.')

finding(16,'Можно уменьшить постоянное потребление INA219 программным режимом ожидания','Низкая','Необязательное улучшение',
 'POWER U12 INA219, штатный continuous режим драйвера MeshCore.',
 'INA219 потребляет типично 0,7 мА, до 1 мА от SYS_3V3 в continuous режиме. Добавление INA было согласовано; требование конкретной длительности автономности не задано. Этот расход не назван током сна всей системы.',
 'При редких измерениях непрерывная работа расходует больше батареи, чем режим shutdown между выборками. Она не нарушает установленную схему и не блокирует изготовление.',
 ext('https://www.ti.com/lit/ds/symlink/ina219.pdf','TI INA219 SBOS448G, electrical characteristics/configuration')+'; '+app('SOFTWARE_BOM_REPORT_RU.md')+'.',
 'После обязательной квалификации оценить интервальные измерения/программный shutdown, если это совместимо с требуемой телеметрией. Сейчас прошивка не изменена.',
 'Сравнить средний ток и восстановление конверсии/калибровки при одинаковом профиле; значения INA остаются корректными после wake. Критерий энергопотребления установить по реальной задаче автономности.',
 'Оптимизация согласованного нового измерителя; не исправление подтверждённого дефекта.')

