def table(headers,rows):
 return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def render_finding(f):
 cl='critical' if f['severity'].startswith('Крит') else 'high' if f['severity']=='Высокая' else ''
 fields=[('Место',f['where']),('Факт и требование',f['fact']),('Условия и последствия',f['conditions']),('Доказательства и предел вывода',f['evidence']),('Минимальное предложение',f['proposal']),('Проверка и приёмка',f['test']),('Происхождение',f['origin'])]
 return f'<article id="{f["id"]}" class="{cl}"><h3>{f["id"]} · {f["title"]}</h3><p class="badge">{f["severity"]} · {f["status"]}</p>'+''.join(f'<p><b>{k}.</b> {v}</p>' for k,v in fields)+'</article>'

parts=['<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mesh Repeater 2.0 A3 — независимый инженерный аудит 13.10.2026</title><style>'+CSS+'</style></head><body><main>']
parts.append('''<p class="meta">Независимый инженерный аудит · 13 октября 2026 · только текущая рабочая v2</p><h1>Mesh Repeater 2.0: A3 с локальными изменениями</h1><div class="lead"><p><b>Безусловная готовность изделия не подтверждена.</b> Два наиболее существенных риска LTO: балансиры с 2 Ω не гарантируют допустимый ток LMV431; при снятой батарее зарядник может вывести VIN TPS63802 за рабочие 5,5 В. Оба риска ранее согласованно оставлены; аудит не отменяет это решение и не считает его доказательством безопасности.</p><p>Также не закрыты паспорт аккумуляторов/панели, пуск и LC, USB через модифицированный клон, реальное сопряжение Ali-пары и противоречие GPS-карты. Подтверждены ошибки действующей документации (указатели A2 и направления UART) и несоответствие маркировки опубликованным минимальным нормам Резонита.</p><p><b>Свежие ERC/DRC чистые; функциональные связи/GPIO сохранены; силового обхода J11 нет; номинальные межплатные пересечения 0 мм³.</b> Эти результаты относятся к CAD и не заменяют измерения питания, радио, температуры и реальную сборку.</p></div>''')
parts.append('<nav><a href="#findings">Реестр замечаний</a><a href="#object">Объект и требования</a><a href="#checks">Выполненные проверки</a><a href="#plan">План и испытания</a><a href="#readiness">Готовность</a><a href="#preservation">Сохранность исходников</a></nav>')
parts.append('<h2 id="findings">Реестр замечаний</h2><p>Критичность описывает возможные последствия; статус отдельно показывает доказанность. Измеренных отказов нет. Все предложения оставлены без внесения в проект. Предварительные E/F/M/R приложения объединены в стабильные V2-AUD; их пересечения не считаются дополнительными замечаниями.</p>')
parts.append(table(['ID','Находка','Критичность','Статус'],[[f'<a href="#{f["id"]}">{f["id"]}</a>',f['title'],f['severity'],f['status']] for f in F if f['id']!='V2-AUD-016']))
